begin;lock table public.campaigns,public.campaign_content_entries,public.campaign_state_fragments,public.campaign_character_versions,public.official_content_entries in share row exclusive mode;do $text$ begin if(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')<>1721 then raise exception 'ITEM_TEXT_CAMPAIGN_CONFLICT';end if;if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:d2c9cf7c7304dbd37f8bc7e1' and md5(to_jsonb(t)::text)='2f4f8bd3f35001bf4b39f146449c21a1')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:d2c9cf7c7304dbd37f8bc7e1';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_dc07da072c2b7578$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras embraces este escudo, obtienes un bonificador de +2 a la CA contra ataques a distancia. Este bonificador se suma al bonificador a la CA normal del escudo. Además, cuando una criatura realice un ataque a distancia contra un objetivo que esté a 1,5 m o menos de ti, podrás usar tu reacción para convertirte en el objetivo del ataque.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_dc07da072c2b7578$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:d2c9cf7c7304dbd37f8bc7e1';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:d33208f224791802d5cc9023' and md5(to_jsonb(t)::text)='dd7ddb601de59462d154f1a05e989053')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:d33208f224791802d5cc9023';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_fb0110dc01b844c7$"Objeto · Precio base · Peso\nMochila · 2 po · 5 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_fb0110dc01b844c7$::jsonb,true),'{rules,definition,description}',$text_467c0a803342b9d2$[{"id":"official-table","rows":[["Mochila","2 po","5 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_467c0a803342b9d2$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:d33208f224791802d5cc9023';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:d3916bc71ae13afb7a224244' and md5(to_jsonb(t)::text)='1335bca776cac7c65cda20516ca12433')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:d3916bc71ae13afb7a224244';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_57ad9bd72f8bcb37$"Objeto · Precio base · Peso\nAntorcha · 1 pc · 1 lb\n\nAntorcha. Una antorcha arde durante 1 hora y emite luz brillante en un radio de 6 m y luz tenue otros 6 m más allá. Si realizas un ataque cuerpo a cuerpo con una antorcha encendida e impactas, causarás 1 de daño de fuego.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_57ad9bd72f8bcb37$::jsonb,true),'{features}',$text_de7c9fd07470e6fa$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Antorcha. Una antorcha arde durante 1 hora y emite luz brillante en un radio de 6 m y luz tenue otros 6 m más allá. Si realizas un ataque cuerpo a cuerpo con una antorcha encendida e impactas, causarás 1 de daño de fuego.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_de7c9fd07470e6fa$::jsonb,true),'{rules,definition,description}',$text_5a4b49e76e85ed57$[{"id":"official-table","rows":[["Antorcha","1 pc","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Antorcha. Una antorcha arde durante 1 hora y emite luz brillante en un radio de 6 m y luz tenue otros 6 m más allá. Si realizas un ataque cuerpo a cuerpo con una antorcha encendida e impactas, causarás 1 de daño de fuego.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_5a4b49e76e85ed57$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:d3916bc71ae13afb7a224244';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:d45091cecb894506094369a2' and md5(to_jsonb(t)::text)='845ddee1feee19c7784bfe8fbeca1c87')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:d45091cecb894506094369a2';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_e1677d9db3bc1981$[{"id":"legacy-bonus-0","kind":"passive","name":"All","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga un bonificador de +1 a todas las tiradas de salvación.","showInActions":false},{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta túnica negra o azul oscura lleva bordadas pequeñas estrellas blancas o plateadas. Mientras la lleves puesta, recibirás un bonificador de +1 a las tiradas de salvación.\n\nSeis de las estrellas, situadas en la parte superior delantera de la túnica, son especialmente grandes. Mientras lleves puesta esta túnica, podrás utilizar una acción para arrancar una de las estrellas y usarla para lanzar proyectil mágico como un conjuro de nivel 5. Cada día al amanecer, 1d6 estrellas arrancadas reaparecerán en la túnica.\n\nMientras lleves puesta la túnica, podrás utilizar una acción para entrar en el Plano Astral junto con todo lo que vistas o lleves. Permanecerás allí hasta que utilices una acción para volver al plano en el que estabas. Reaparecerás en el último espacio que ocupabas o, si el espacio ya está ocupado, en el espacio sin ocupar más cercano.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_e1677d9db3bc1981$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:d45091cecb894506094369a2';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:d557752500840d78b5e905d8' and md5(to_jsonb(t)::text)='d2fa4323b883baf91198aa3bb80f9afc')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:d557752500840d78b5e905d8';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_dd50717b3781ab10$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando impactes con un ataque usando esta espada mágica, el objetivo recibirá 1d6 de daño de frío adicional. Además, mientras empuñes la espada, tendrás resistencia al daño de fuego.\n\nEn temperaturas bajo cero, la espada emite luz brillante en un radio de 3 m y luz tenue 3 m más allá.\n\nCuando desenvainas esta arma, puedes extinguir todas las llamas no mágicas que haya a 9 m o menos de ti. Esta propiedad no puede emplearse más de una vez por hora.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_dd50717b3781ab10$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:d557752500840d78b5e905d8';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:d613ca81a782e29c124eff8f' and md5(to_jsonb(t)::text)='195958812903b0fc65b41aa2752a3a8f')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:d613ca81a782e29c124eff8f';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_fbbab4029ece3564$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Estas lentes de cristal cubren los ojos. Mientras las lleves puestas, podrás ver mucho mejor de lo normal hasta una distancia de 30 cm. Tendrás ventaja en las pruebas de Inteligencia (Investigación) que dependan de la vista si examinas una zona o estudias un objeto que se encuentre a esa distancia o menos.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_fbbab4029ece3564$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:d613ca81a782e29c124eff8f';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:d6f94e0376d1900f4c11bb8c' and md5(to_jsonb(t)::text)='227ccd70930f8f04095ffa47e8106c1e')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:d6f94e0376d1900f4c11bb8c';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_61b09f21613118e3$"Objeto · Precio base · Peso · Unidades por paquete · Peso por unidad (lb) · Precio por unidad (pc)\nPincho de hierro · 1 po · 5 lb · 10 · 0.5 · 10\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_61b09f21613118e3$::jsonb,true),'{rules,definition,description}',$text_ca94dda6590b5857$[{"id":"official-table","rows":[["Pincho de hierro","1 po","5 lb","10","0.5","10"]],"type":"table","columns":["Objeto","Precio base","Peso","Unidades por paquete","Peso por unidad (lb)","Precio por unidad (pc)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_ca94dda6590b5857$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:d6f94e0376d1900f4c11bb8c';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:d81d22e38c3ddd4e620b5674' and md5(to_jsonb(t)::text)='316df8d503b6321626502a418d537eb5')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:d81d22e38c3ddd4e620b5674';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_7a23c041d535fc2b$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, recuperarás 1d6 puntos de golpe cada 10 minutos, siempre y cuando tengas al menos 1 punto de golpe. Si pierdes una parte del cuerpo, el anillo hace que te vuelva a crecer y recupere su funcionalidad completa tras 1d6 + 1 días si te mantienes con al menos 1 punto de golpe durante todo ese tiempo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_7a23c041d535fc2b$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:d81d22e38c3ddd4e620b5674';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:d837a9dc165434a7ebb4b2bb' and md5(to_jsonb(t)::text)='5e8c1040a50b424f33a024756c9e6d46')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:d837a9dc165434a7ebb4b2bb';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_62756aacf630eddf$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Estas herraduras de hierro vienen de cuatro en cuatro. Mientras cuatro de ellas estén fijadas a los cascos de un caballo o de una criatura similar, le permitirán moverse con normalidad mientras flota 10 cm por encima del suelo. Este efecto implica que la criatura puede cruzar o permanecer sobre superficies no sólidas o inestables, como agua y lava. Además, no deja huellas e ignora el terreno difícil. Asimismo, la criatura podrá moverse a velocidad normal durante 12 horas al día, como máximo, sin padecer cansancio por hacer marchas forzadas.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_62756aacf630eddf$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:d837a9dc165434a7ebb4b2bb';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:d853aa97a9cf8e6489371efd' and md5(to_jsonb(t)::text)='3a3853378a131d9b63be6304a0537db8')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:d853aa97a9cf8e6489371efd';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_ffeec24cc9187eb8$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica.\n\nCuando impactes a un dragón con esta arma, este sufrirá 3d6 de daño adicional del tipo del arma. En lo que concierne a esta arma, “dragón” se refiere a cualquier criatura con el tipo “dragón”, incluidos seres como dragones tortuga y guivernos.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_ffeec24cc9187eb8$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:d853aa97a9cf8e6489371efd';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:d857ec4ef6d77131aa567d47' and md5(to_jsonb(t)::text)='2f188e16db5db491af6e28d103df3faf')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:d857ec4ef6d77131aa567d47';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_3f71c7203bce29d4$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras arda un fuego en este brasero de latón, podrás utilizar una acción para pronunciar su palabra de activación e invocar un elemental de fuego, como si hubieras lanzado conjurar elemental. El brasero no puede volver a emplearse de esta manera hasta el siguiente amanecer.\n\nEl brasero pesa 2,5 kg.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_3f71c7203bce29d4$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:d857ec4ef6d77131aa567d47';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:d8a3f2f409a708360ac1156f' and md5(to_jsonb(t)::text)='39184fad69aab11ee91cc20935ba71fa')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:d8a3f2f409a708360ac1156f';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_ffc941d8b32c6a46$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas para utilizar las propiedades que se describen a continuación. Recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.\n\nConjuros. Mientras empuñes la varita, podrás usar una acción y gastar algunas de sus cargas para lanzar uno de los siguientes conjuros (CD de salvación 17): inmovilizar monstruo (5 cargas) o inmovilizar persona (2 cargas).\n\nEscape asistido. Mientras empuñes la varita, podrás usar tu reacción para gastar 1 carga y obtener ventaja en una tirada de salvación que realices para evitar que te apresen o paralicen, o puedes emplear 1 carga para obtener ventaja en cualquier prueba que hagas para escapar de un agarre.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_ffc941d8b32c6a46$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:d8a3f2f409a708360ac1156f';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:d915713ec2c391e5dcf80714' and md5(to_jsonb(t)::text)='6fc4f62e301664ceb14eb36ceae7af48')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:d915713ec2c391e5dcf80714';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_5615c435e74bef0a$"Objeto · Precio base · Peso\nRaciones (1 día) · 5 pp · 2 lb\n\nRaciones. Las raciones contienen alimentos secos que resisten viajes largos, como cecina, fruta deshidratada, galletas y nueces.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_5615c435e74bef0a$::jsonb,true),'{features}',$text_6268396968fa5288$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Raciones. Las raciones contienen alimentos secos que resisten viajes largos, como cecina, fruta deshidratada, galletas y nueces.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_6268396968fa5288$::jsonb,true),'{rules,definition,description}',$text_f8f536bb79fb87b3$[{"id":"official-table","rows":[["Raciones (1 día)","5 pp","2 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Raciones. Las raciones contienen alimentos secos que resisten viajes largos, como cecina, fruta deshidratada, galletas y nueces.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_f8f536bb79fb87b3$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:d915713ec2c391e5dcf80714';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:d9b601a829486f58d1edab2a' and md5(to_jsonb(t)::text)='479853ac1e90a8a457df1640b8812856')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:d9b601a829486f58d1edab2a';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_765086698ac323cb$[{"id":"official-base-table","rows":[["Guja","20 po","6 lb","1d10 cortante","+0","Pesada, Gran alcance, A dos manos"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-heavy","text":"Pesada. Las criaturas Pequeñas tienen desventaja en las tiradas de ataque con armas pesadas. Su tamaño y peso hacen que sean demasiado voluminosas para que una criatura Pequeña las use con efectividad.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-reach","text":"Gran alcance. Cuando empleas un arma de este tipo, tu alcance aumenta en 1,5 m, tanto al atacar como a efectos de ataques de oportunidad.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-two-handed","text":"A dos manos. Estas armas requieren el uso de las dos manos.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_765086698ac323cb$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_84a25ae6b543e731$["official-base-table","property-heavy","property-reach","property-two-handed","family-rule"]$text_84a25ae6b543e731$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:d9b601a829486f58d1edab2a';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:d9e9a9a6ad6074aa856fdb75' and md5(to_jsonb(t)::text)='735420105ce78e5df5df37af36977145')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:d9e9a9a6ad6074aa856fdb75';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_818805f0ac1beb2b$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, tendrás ventaja en las tiradas de salvación contra cualquier conjuro que solo te haga objetivo a ti (no como parte de un área de efecto). Además, si sacas un 20 en la tirada de salvación y el conjuro es de nivel 7 o inferior, el conjuro no tendrá efecto alguno en ti y, en su lugar, hará objetivo al lanzador y utilizará el nivel del espacio de conjuro, la CD de salvación de conjuros, el bonificador de ataque y la aptitud mágica del lanzador.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_818805f0ac1beb2b$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:d9e9a9a6ad6074aa856fdb75';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:da3415c797431ef012a27635' and md5(to_jsonb(t)::text)='d00b2f69c5dc590b6330879bf101b440')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:da3415c797431ef012a27635';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_49e3e80c25fd1c94$[{"id":"lance-special","kind":"other","name":"Uso de la lanza de caballería","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Lanza de caballería. Tendrás desventaja si usas una lanza de caballería para atacar a un objetivo que esté a 1,5 m o menos de ti. Además, si no estás sobre una montura, necesitarás las dos manos para empuñarla.\n\nRequiere dos manos si no se está montado.\n\nDuración: Mientras se utiliza el arma..","showInActions":false}]$text_49e3e80c25fd1c94$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:da3415c797431ef012a27635';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:daca2184e53f2ea25df94b05' and md5(to_jsonb(t)::text)='5eb1aad0c701df1fe5ff101b112d6de6')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:daca2184e53f2ea25df94b05';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_ad0db3441d684050$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este yelmo, podrás utilizar una acción para lanzar el conjuro detectar pensa- mientos (CD de salvación 13) desde él. Mientras mantengas la concentración en el conjuro, podrás usar una acción adicional para mandar un mensaje telepático a una criatura en la que te estés concen- trando. Podrá responderte usando una acción adicional mientras te concentres en ella.\n\nMientras te concentres en una criatura con detectar pensamientos, podrás utilizar una acción para lanzar el conjuro sugestión (CD de salvación 13) desde el yelmo sobre esa criatura. Una vez utilizada, la propiedad sugestión no puede volver a usarse hasta el siguiente amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_ad0db3441d684050$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:daca2184e53f2ea25df94b05';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:db68a706e3edbdffed736118' and md5(to_jsonb(t)::text)='cbcee2ca7dabb9ba7f9f8714801aad7e')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:db68a706e3edbdffed736118';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_7ee10a6b1ec9aba7$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves estos guantes, nadar y escalar no te costará movimiento adicional y obtendrás un bonificador de +5 a las pruebas de Fuerza (Atletismo) que hagas para nadar o escalar.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_7ee10a6b1ec9aba7$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:db68a706e3edbdffed736118';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:db7d1b79dc665d3f57d5d2c2' and md5(to_jsonb(t)::text)='219988a7afee49998d951657150f1eff')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:db7d1b79dc665d3f57d5d2c2';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_dde479bbe9eae2a6$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta botella de latón pintado pesa 0,5 kg. Cuando uses una acción para quitar el tapón, una nube de humo denso saldrá de la botella. Al final de tu turno, el humo desaparece con un fogonazo inofensivo y un ifrit se manifestará en un espacio sin ocupar a 9 m o menos de ti.\n\nLa primera vez que se abra la botella, tu GM tirará para determina lo que ocurre.\n\n01–10 · El ifrit te ataca. Tras luchar durante 5 asaltos, el ifrit desaparecerá y la botella perderá su magia.\n11–90 · El ifrit te sirve durante 1 hora y hace lo que le ordenes. A continuación, regresará a la botella y un nuevo tapón le impedirá salir. El tapón no se puede quitar durante 24 horas. Las dos siguientes veces que se abra la botella, ocurrirá el mismo efecto. Si la botella se abre una cuarta vez, el ifrit se escapará y desaparecerá, y la botella perderá su magia.\n91–00 · El ifrit puede lanzar el conjuro deseo tres veces para ti. Desaparecerá cuando conceda el último deseo o después de 1 hora y la botella perderá su magia.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_dde479bbe9eae2a6$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:db7d1b79dc665d3f57d5d2c2';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:db828358f6811c9a673a2d57' and md5(to_jsonb(t)::text)='edb3f874e7a2fd4d3ff8665be20b628d')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:db828358f6811c9a673a2d57';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_1c4fc0657463d9e9$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"El humo se filtra a través del tapón de plomo de esta botella de latón, que pesa 0,5 kg. Cuando uses una acción para quitar el tapón, una nube de humo denso saldrá de la botella y cubrirá un radio de 18 m. La zona que ocupa la nube estará muy oscura. Cada minuto que la botella permanezca abierta y dentro de la nube, el radio aumentará en 3 m hasta que alcance su máximo de 36 m.\n\nLa nube permanecerá mientras la botella esté abierta. Para cerrarla, tienes que utilizar una acción para pronunciar su palabra de activación. Una vez que se cierre la botella, la nube se disipará tras 10 minutos. Un viento moderado (de 15 a 30 km/h) también puede dispersar el humo en 1 minuto y un viento fuerte (más de 30 km/h) lo hará en 1 asalto.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_1c4fc0657463d9e9$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:db828358f6811c9a673a2d57';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:dbdd04e383a8cd140b7f0c66' and md5(to_jsonb(t)::text)='3046ea8d9022d18a8edc8f9d482ee9fb')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:dbdd04e383a8cd140b7f0c66';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_39b77e31a352c43e$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este aceite transparente y gelatinoso brilla debido a las minúsculas esquirlas de plata que contiene. Puede impregnar un arma cortante o perforante o hasta 5 unidades de munición cortante o perforante. Aplicar el aceite lleva 1 minuto. Durante 1 hora, el objeto impregnado es mágico y tiene un bonificador de +3 a las tiradas de ataque y de daño.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$text_39b77e31a352c43e$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:dbdd04e383a8cd140b7f0c66';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:dca7ce044bc3a61a7d7975a9' and md5(to_jsonb(t)::text)='3a83544290d3e572749569e5dc181deb')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:dca7ce044bc3a61a7d7975a9';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_e79cf78b61c71d5c$[{"id":"official-base-table","rows":[["Garrote grande","2 pp","10 lb","1d8 contundente","+0","A dos manos"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-two-handed","text":"A dos manos. Estas armas requieren el uso de las dos manos.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_e79cf78b61c71d5c$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_e6cd23a649030657$["official-base-table","property-two-handed","family-rule"]$text_e6cd23a649030657$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:dca7ce044bc3a61a7d7975a9';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:ddb03c90d649ff901a595dfd' and md5(to_jsonb(t)::text)='0c63df74a1150b05becdb34f481f1480')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:ddb03c90d649ff901a595dfd';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_a5c1642dce15fd53$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras embraces este escudo, tendrás ventaja en las tiradas de salvación contra conjuros y otros efectos mágicos, y los ataques de conjuro tendrán desventaja contra ti.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_a5c1642dce15fd53$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:ddb03c90d649ff901a595dfd';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:dfac5d1193ee8763411386fa' and md5(to_jsonb(t)::text)='6b4677ad7a91409b3bf7ce7bb1ccfa54')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:dfac5d1193ee8763411386fa';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_7bc718f5417070c9$[{"id":"official-use","kind":"other","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cada uno de los tres compartimentos de esta aljaba está conectado con un espacio extradimensional, lo que le permite contener muchos objetos sin pesar nunca más de 1 kg. El compartimento más pequeño puede albergar hasta 60 flechas, virotes u objetos similares. El compartimento intermedio puede contener hasta 18 jabalinas u objetos parecidos. En el compartimento más grande caben hasta 6 objetos largos, como arcos, bastones o lanzas.\n\nPuedes extraer cualquier objeto que contenga esta aljaba igual que lo harías con una aljaba o vaina normal.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_7bc718f5417070c9$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:dfac5d1193ee8763411386fa';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:dfe4f67404619490ab853e9d' and md5(to_jsonb(t)::text)='af2d1972649d44b98be9ee2b209160b1')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:dfe4f67404619490ab853e9d';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_f0e511db536bffb9$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Los puntos de golpe perdidos por el daño de esta arma solo pueden recuperarse mediante un descanso corto o largo, no mediante la regeneración, la magia o cualquier otro medio.\n\nUna vez por turno, cuando impactes a una criatura con un ataque usando esta arma mágica, podrás herirla. Al principio de cada turno de la criatura herida, sufrirá 1d4 de daño necrótico por cada vez que la hayas herido y luego podrá realizar una tirada de salvación de Constitución con CD 15 para acabar con el efecto de esas heridas si la supera. Como alternativa, la criatura herida u otra que se encuentre a 1,5 m o menos de ella podrá usar una acción para realizar una prueba de Sabiduría (Medicina) con CD 15 y acabar con el efecto de las heridas si la supera.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f0e511db536bffb9$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:dfe4f67404619490ab853e9d';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:e14cde6c9aac3e864c054708' and md5(to_jsonb(t)::text)='46a3853034638ae5c644594ac48e54bd')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:e14cde6c9aac3e864c054708';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_098e651649ff7d4d$[{"id":"mundane-assisted-use","kind":"other","name":"Jugar con competencia","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Set de Juego. Este objeto engloba un amplio rango de piezas de juego incluyendo dados y barajas de cartas (para juegos tales como Tres dragones). Unos pocos ejemplos comunes aparecen en la tabla Herramientas pero existen otro tipo de sets de juego. Si eres competente con un set de juego puedes añadir tu bonificador de competencia a las pruebas de característica que realices para jugar a un juego con este set. Cada tipo de set de juego requiere una competencia por separado.\n\nDuración: Según su uso..","showInActions":false}]$text_098e651649ff7d4d$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:e14cde6c9aac3e864c054708';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:e195a30cf2bed9617cab705d' and md5(to_jsonb(t)::text)='81a1cb7533d60dd66bce39ed07c6d2a9')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:e195a30cf2bed9617cab705d';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_fceb5fda75291662$[{"id":"official-base-table","rows":[["Martillo ligero","2 po","2 lb","1d4 contundente","+0","Ligera, Arrojadiza","20/60"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-light","text":"Ligera. Un arma ligera es pequeña y fácil de manejar, así que resulta ideal para luchar con dos armas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-thrown","text":"Arrojadiza. Si un arma tiene esta propiedad, puedes lanzarla para realizar un ataque a distancia. Si se trata de un arma cuerpo a cuerpo, harás las tiradas de ataque y de daño con el mismo modificador que emplearías para hacer un ataque cuerpo a cuerpo con el arma. Por ejemplo, si lanzas un hacha de mano, utilizarás tu Fuerza, pero si arrojas una daga, podrás elegir entre usar la Fuerza o la Destreza, ya que la daga también posee la propiedad “sutil”.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_fceb5fda75291662$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_f30737b33e327572$["official-base-table","property-light","property-thrown","family-rule"]$text_f30737b33e327572$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:e195a30cf2bed9617cab705d';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:e22d639500fbb1d59085b9a5' and md5(to_jsonb(t)::text)='501bf62974e50b915019b4ca69f948d8')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:e22d639500fbb1d59085b9a5';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_9695271bece60149$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta capa, tendrás ventaja en las tiradas de salvación contra conjuros.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_9695271bece60149$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:e22d639500fbb1d59085b9a5';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:e2c6fc0f3a4001fca0154c52' and md5(to_jsonb(t)::text)='b66170957484fb28576ce08e5fdb56d5')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:e2c6fc0f3a4001fca0154c52';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_29de674beabfb97f$"Objeto · Precio base · Peso\nFuego de alquimista (frasco) · 50 po · 1 lb\n\nFuego de alquimista. Este fluido pegajoso y adherente prende al entrar en contacto con el aire. Como acción, puedes lanzar este frasco hasta a 6 m, lo que hará que se rompa con el impacto. Haz un ataque a distancia contra una criatura u objeto y trata el fuego de alquimista como un arma improvisada. Si impacta, el objetivo sufre 1d4 de daño de fuego al principio de cada uno de sus turnos. Una criatura puede poner fin a este efecto si usa su acción para realizar una prueba de Destreza con CD 10 para extinguir las llamas.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_29de674beabfb97f$::jsonb,true),'{features}',$text_e827c91874ef8602$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Fuego de alquimista. Este fluido pegajoso y adherente prende al entrar en contacto con el aire. Como acción, puedes lanzar este frasco hasta a 6 m, lo que hará que se rompa con el impacto. Haz un ataque a distancia contra una criatura u objeto y trata el fuego de alquimista como un arma improvisada. Si impacta, el objetivo sufre 1d4 de daño de fuego al principio de cada uno de sus turnos. Una criatura puede poner fin a este efecto si usa su acción para realizar una prueba de Destreza con CD 10 para extinguir las llamas.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_e827c91874ef8602$::jsonb,true),'{rules,definition,description}',$text_fc80bfec3e404bfa$[{"id":"official-table","rows":[["Fuego de alquimista (frasco)","50 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Fuego de alquimista. Este fluido pegajoso y adherente prende al entrar en contacto con el aire. Como acción, puedes lanzar este frasco hasta a 6 m, lo que hará que se rompa con el impacto. Haz un ataque a distancia contra una criatura u objeto y trata el fuego de alquimista como un arma improvisada. Si impacta, el objetivo sufre 1d4 de daño de fuego al principio de cada uno de sus turnos. Una criatura puede poner fin a este efecto si usa su acción para realizar una prueba de Destreza con CD 10 para extinguir las llamas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_fc80bfec3e404bfa$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:e2c6fc0f3a4001fca0154c52';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:e3acaffca731d7c31f0bfeff' and md5(to_jsonb(t)::text)='7384338d299cae546649f6780e3096eb')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:e3acaffca731d7c31f0bfeff';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_12efb51145f6de93$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción para colocar este cubo metálico de 2,5 cm de lado en el suelo y pronunciar su palabra de activación. El cubo se convertirá rápidamente en una fortaleza que permanecerá hasta que emplees una acción para pronunciar la palabra de activación que la hace desaparecer, que solo funcionará si la fortaleza está vacía.\n\nEsta fortificación es una torre cuadrada de 6 m de lado y 9 m de altura, con aspilleras en todos los lados y almenas en la parte superior. Su interior se divide en dos plantas conectadas mediante una escalera que recorre una de las paredes. La escalera termina en una trampilla que conduce al tejado. Cuando se activa, la torre tiene una puerta pequeña en el lado que mira hacia ti. La puerta se abre solo bajo tus órdenes, que puedes dar como acción adicional. Es inmune al conjuro abrir y otros efectos mágicos similares, como el de un carillón de apertura.\n\nTodas las criaturas situadas en la zona en la que aparezca la fortaleza deberán realizar una tirada de salvación de Destreza con CD 15; sufrirán 10d10 de daño contundente si la fallan o la mitad del daño si la superan. En ambos casos, cada criatura será empujada a un espacio sin ocupar junto a la fortaleza, pero fuera de ella. Los objetos situados en la zona y que no lleve o vista alguien sufrirán este daño y serán empujados automáticamente.\n\nLa torre está hecha de adamantina y su magia impide que la derriben. El tejado, la puerta y las paredes tienen 100 puntos de golpe cada uno, inmunidad al daño de armas no mágicas (salvo armas de asedio) y resistencia al resto de daño. Solo un conjuro deseo puede reparar la fortaleza (este uso cuenta como replicar un conjuro de nivel 8 o inferior). Cada vez que se lance deseo, el tejado, la puerta o una pared recuperará 50 puntos de golpe.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_12efb51145f6de93$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:e3acaffca731d7c31f0bfeff';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:e59b07ec950530f903759662' and md5(to_jsonb(t)::text)='ea964421973545e1a8caff2a88b5ca60')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:e59b07ec950530f903759662';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_bdb52a76377c1eea$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando ataques a un objeto con esta espada mágica e impactes, toma el resultado máximo de los dados de daño del arma contra el objetivo.\n\nCuando ataques a una criatura con esta arma y saques un 20 en la tirada de ataque, el objetivo sufrirá 4d6 de daño cortante adicional. A continuación, tira otro d20. Si sacas un 20, seccionarás uno de los miembros del objetivo. Tu GM determinará el efecto de esta amputación. Si la criatura no tiene ningún miembro que se pueda amputar, en vez de ello, seccionarás otra parte de su cuerpo.\n\nAdemás, puedes pronunciar la palabra de activación de la espada para hacer que la hoja emita luz brillante en un radio de 3 m y luz tenue 3 m más allá. Si vuelves a pronunciar la palabra de activación o envainas la espada, apagarás la luz.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_bdb52a76377c1eea$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:e59b07ec950530f903759662';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:e6f279561dbf73cf66121000' and md5(to_jsonb(t)::text)='8809fad842b9b2423be220e0f56032f1')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:e6f279561dbf73cf66121000';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_74bbd0eb847ed37e$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesta esta capa, podrás utilizar una acción para pronunciar su palabra de activación. La capa se convertirá en unas alas de murciélago o de pájaro que se colocan a tu espalda durante 1 hora o hasta que repitas la palabra de activación como acción. Las alas te otorgan una velocidad volando de 18 m. Cuando desaparezcan, no podrás usarlas de nuevo durante 1d12 horas.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_74bbd0eb847ed37e$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:e6f279561dbf73cf66121000';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:e6fb55a58513814680574185' and md5(to_jsonb(t)::text)='97bc3453fc451fa8e5810af9d5a9ed9c')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:e6fb55a58513814680574185';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_66537621eea405a8$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este libro contiene indicaciones para influir y embelesar a los demás, y sus palabras están impregnadas de magia. Si dedicas 48 horas durante un periodo de 6 días, como mucho, a estudiar el contenido del libro y poner en práctica sus indicaciones, tu puntuación de Carisma aumentará en 2, así como tu máximo para esa puntuación. Después, el manual perderá su magia, pero la recuperará cuando pase un siglo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_66537621eea405a8$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:e6fb55a58513814680574185';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:e71f1a3639d0ca163bea1a3f' and md5(to_jsonb(t)::text)='915cce2ef0a6a75aaba98b0bdd2fe8ee')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:e71f1a3639d0ca163bea1a3f';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_d20dc719ee200707$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción y gastar 1 de sus cargas para lanzar el conjuro telaraña (CD de salvación 15) desde ella.\n\nLa varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_d20dc719ee200707$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:e71f1a3639d0ca163bea1a3f';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:e994633540f2d0f6fe235b6b' and md5(to_jsonb(t)::text)='1905bf7792e1c94ccfc2f8c990df720d')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:e994633540f2d0f6fe235b6b';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_dd50717b3781ab10$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando impactes con un ataque usando esta espada mágica, el objetivo recibirá 1d6 de daño de frío adicional. Además, mientras empuñes la espada, tendrás resistencia al daño de fuego.\n\nEn temperaturas bajo cero, la espada emite luz brillante en un radio de 3 m y luz tenue 3 m más allá.\n\nCuando desenvainas esta arma, puedes extinguir todas las llamas no mágicas que haya a 9 m o menos de ti. Esta propiedad no puede emplearse más de una vez por hora.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_dd50717b3781ab10$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:e994633540f2d0f6fe235b6b';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:ea969a49b5350a175ac19b83' and md5(to_jsonb(t)::text)='c3dec7d8e91e58545f583807067a8459')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:ea969a49b5350a175ac19b83';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_36fbd84554054a1f$[{"id":"official-base-table","rows":[["Daga","2 po","1 lb","1d4 perforante","+0","Sutil, Ligera, Arrojadiza","20/60"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-finesse","text":"Sutil. Cuando ataques con un arma sutil, podrás elegir realizar las tiradas de ataque y de daño con el modificador por Fuerza o con el modificador por Destreza. Eso sí, deberás usar el mismo modificador para ambas tiradas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-light","text":"Ligera. Un arma ligera es pequeña y fácil de manejar, así que resulta ideal para luchar con dos armas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-thrown","text":"Arrojadiza. Si un arma tiene esta propiedad, puedes lanzarla para realizar un ataque a distancia. Si se trata de un arma cuerpo a cuerpo, harás las tiradas de ataque y de daño con el mismo modificador que emplearías para hacer un ataque cuerpo a cuerpo con el arma. Por ejemplo, si lanzas un hacha de mano, utilizarás tu Fuerza, pero si arrojas una daga, podrás elegir entre usar la Fuerza o la Destreza, ya que la daga también posee la propiedad “sutil”.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_36fbd84554054a1f$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_f22b673c4ae12637$["official-base-table","property-finesse","property-light","property-thrown","family-rule"]$text_f22b673c4ae12637$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:ea969a49b5350a175ac19b83';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:eb25c4df5d5bd294667b7d08' and md5(to_jsonb(t)::text)='afb7a3e7770509d899c98ff5ac3a09b2')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:eb25c4df5d5bd294667b7d08';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_7f63cdf0190e902c$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este tridente es un arma mágica. Tiene 3 cargas. Mientras lo lleves contigo, podrás utilizar una acción y gastar 1 carga para lanzar dominar bestia (CD de salvación 15) desde él sobre una bestia que tenga una velocidad nadando innata. El tridente recupera 1d3 cargas empleadas cada día, al amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_7f63cdf0190e902c$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:eb25c4df5d5bd294667b7d08';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:ee49205d290ab9eaafa1108f' and md5(to_jsonb(t)::text)='9464e90893e6f7f51cc162b28b7023e5')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:ee49205d290ab9eaafa1108f';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_37d3cb15a9648010$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este yelmo, podrás utilizar una acción para lanzar a voluntad el conjuro entender idiomas desde él.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_37d3cb15a9648010$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:ee49205d290ab9eaafa1108f';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:ef95f23bd99224f3cdf64a7d' and md5(to_jsonb(t)::text)='8e7f6755b9c0166e12c9c6d5cd26f6f3')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:ef95f23bd99224f3cdf64a7d';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_4548fbeea826434d$[{"id":"store-spells","kind":"other","name":"Almacenar un conjuro","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este anillo almacena los conjuros que se lanzan sobre él y los conserva hasta que el portador sintonizado decida usarlos. El anillo puede guardar conjuros con un valor de hasta 5 niveles. Cuando lo encuentres, contendrá 1d6 − 1 niveles de conjuros almacenados, a elección de tu GM.\n\nCualquier criatura puede lanzar un conjuro de niveles 1 a 5 sobre el anillo si lo toca mientras lanza el conjuro. El único efecto que tendrá el conjuro es que quedará almacenado en el anillo. Si el anillo no puede albergarlo, el conjuro se gastará sin efecto. El nivel del espacio utilizado para lanzar el conjuro determina cuánto espacio utiliza.\n\nMientras lleves puesto este anillo, podrás lanzar cualquiera de los conjuros almacenados. El conjuro utiliza el nivel del espacio, la CD de salvación de conjuros, el bonificador de ataque de conjuros y la aptitud mágica del lanzador original, pero, por lo demás, funciona como si tú lo hubieses lanzado. El conjuro lanzado desde el anillo deja de estar almacenado en él, por lo que deja espacio libre.\n\nDuración: Hasta lanzar el conjuro almacenado..","showInActions":false},{"id":"cast-stored-spell","kind":"other","name":"Lanzar un conjuro almacenado","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este anillo almacena los conjuros que se lanzan sobre él y los conserva hasta que el portador sintonizado decida usarlos. El anillo puede guardar conjuros con un valor de hasta 5 niveles. Cuando lo encuentres, contendrá 1d6 − 1 niveles de conjuros almacenados, a elección de tu GM.\n\nCualquier criatura puede lanzar un conjuro de niveles 1 a 5 sobre el anillo si lo toca mientras lanza el conjuro. El único efecto que tendrá el conjuro es que quedará almacenado en el anillo. Si el anillo no puede albergarlo, el conjuro se gastará sin efecto. El nivel del espacio utilizado para lanzar el conjuro determina cuánto espacio utiliza.\n\nMientras lleves puesto este anillo, podrás lanzar cualquiera de los conjuros almacenados. El conjuro utiliza el nivel del espacio, la CD de salvación de conjuros, el bonificador de ataque de conjuros y la aptitud mágica del lanzador original, pero, por lo demás, funciona como si tú lo hubieses lanzado. El conjuro lanzado desde el anillo deja de estar almacenado en él, por lo que deja espacio libre.\n\nDuración: Según el conjuro almacenado..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4548fbeea826434d$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:ef95f23bd99224f3cdf64a7d';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:efcf9190471450b926304709' and md5(to_jsonb(t)::text)='1dd38cb7e334a2665a1b56b139a53517')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:efcf9190471450b926304709';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_1b9f73811a287e94$"Objeto · Precio base · Peso\nRopas de calidad · 15 po · 6 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_1b9f73811a287e94$::jsonb,true),'{rules,definition,description}',$text_44789f9e192f265d$[{"id":"official-table","rows":[["Ropas de calidad","15 po","6 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_44789f9e192f265d$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:efcf9190471450b926304709';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:f04899b83f054b78715736ed' and md5(to_jsonb(t)::text)='41df06d7d1529d629d4718163f6d1da8')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:f04899b83f054b78715736ed';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_6adf0937c2fb14b1$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este libro describe diferentes ejercicios para mantenerse en forma y sus palabras están impregnadas de magia. Si dedicas 48 horas durante un periodo de 6 días, como mucho, a estudiar el contenido del libro y poner en práctica sus indicaciones, tu puntuación de Fuerza aumentará en 2, así como tu máximo para esa puntuación. Después, el manual perderá su magia, pero la recuperará cuando pase un siglo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_6adf0937c2fb14b1$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:f04899b83f054b78715736ed';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:f16f5c78093a9e8470217e65' and md5(to_jsonb(t)::text)='389ce1839ffecea07a0942e28e91f30e')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:f16f5c78093a9e8470217e65';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_a6c587cf49df5be5$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta cuerda de seda de 18 m de longitud pesa 1,5 kg y puede soportar hasta 1500 kg. Si sujetas uno de los extremos de la cuerda y utilizas una acción para pronunciar la palabra de activación, la cuerda cobrará vida. Como acción adicional, puedes ordenar al otro extremo que se mueva hacia un destino que elijas. Ese extremo se moverá 3 m en tu turno cuando le des la orden por primera vez y 3 m en cada uno de tus turnos hasta que llegue a su destino, hasta que alcance su longitud máxima o hasta que le mandes parar. También puedes ordenar a la cuerda que se ate de forma segura a un objeto, se desate, se anude o se desanude, o se enrolle para transportarla.\n\nSi le ordenas que se anude, se formarán unos nudos grandes en intervalos de 30 cm a lo largo de la cuerda. Mientras esté anudada, la cuerda reduce su longitud a 15 m y otorga ventaja en las pruebas que se realicen para escalarla.\n\nLa cuerda tiene una CA de 20 y 20 puntos de golpe. Recupera 1 punto de golpe cada 5 minutos mientras tenga al menos 1 punto de golpe. Si los puntos de golpe de la cuerda se reducen a 0, se destruye.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_a6c587cf49df5be5$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:f16f5c78093a9e8470217e65';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:f2e134338fbb17f190d3f817' and md5(to_jsonb(t)::text)='dc6dd2e156c6e936a6cd07247a5ec97d')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:f2e134338fbb17f190d3f817';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_08989937f975ed3b$"Objeto · Precio base · Peso\nOrbe · 20 po · 3 lb\n\nCanalizador arcano. Un canalizador arcano es un objeto especial, diseñado para conducir el poder de los conjuros arcanos. Puede ser un orbe, un cristal, un cetro, un bastón fabricado específicamente con este fin, un trozo de madera con forma de varita o un objeto similar. Los brujos, hechiceros y magos pueden utilizar este objeto como canalizador mágico.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_08989937f975ed3b$::jsonb,true),'{features}',$text_7f0fd4e9063deb6a$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Canalizador arcano. Un canalizador arcano es un objeto especial, diseñado para conducir el poder de los conjuros arcanos. Puede ser un orbe, un cristal, un cetro, un bastón fabricado específicamente con este fin, un trozo de madera con forma de varita o un objeto similar. Los brujos, hechiceros y magos pueden utilizar este objeto como canalizador mágico.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_7f0fd4e9063deb6a$::jsonb,true),'{rules,definition,description}',$text_528ba96b62b1dcb8$[{"id":"official-table","rows":[["Orbe","20 po","3 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Canalizador arcano. Un canalizador arcano es un objeto especial, diseñado para conducir el poder de los conjuros arcanos. Puede ser un orbe, un cristal, un cetro, un bastón fabricado específicamente con este fin, un trozo de madera con forma de varita o un objeto similar. Los brujos, hechiceros y magos pueden utilizar este objeto como canalizador mágico.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_528ba96b62b1dcb8$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:f2e134338fbb17f190d3f817';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:f3000567c773f6c02cfb2957' and md5(to_jsonb(t)::text)='eb4c7b776754d73485a419a7b813ee57')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:f3000567c773f6c02cfb2957';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_b5311f5ea949dadf$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes usar una acción para poner estos grilletes a una criatura incapacitada. Se ajustan a criaturas de tamaños Pequeño a Grande. Además de servir como unas esposas normales, los grilletes impiden que la criatura utilice cualquier método de movimiento extradimensional, incluidos la teletransportación o los viajes a otro plano de existencia. No impiden que la criatura atraviese un portal interdimensional.\n\nTú y cualquier criatura que designes al usar los grilletes podéis emplear una acción para quitarlos. Una vez cada 30 días, la criatura esposada podrá realizar una prueba de Fuerza (Atletismo) con CD 30. Si la supera, se liberará y destruirá los grilletes.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_b5311f5ea949dadf$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:f3000567c773f6c02cfb2957';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:f3814673135c5a3a0681325d' and md5(to_jsonb(t)::text)='3df49bffc4481d1bfeaf1c8e3ca141ca')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:f3814673135c5a3a0681325d';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_78cacd5c998f65d7$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este anillo está vinculado a uno de los cuatro Planos Elementales. Tu GM elige el plano o lo determina al azar.\n\nMientras lo lleves puesto, tendrás ventaja en las tiradas de ataque contra elementales del plano vinculado y ellos tendrán desventaja en las tiradas de ataque contra ti. Además, tendrás acceso a ciertas propiedades en función del plano vinculado.\n\nEl anillo tiene 5 cargas. Recupera 1d4 +1 cargas empleadas cada día, al amanecer. Los conjuros lanzados desde el anillo tienen una CD de salvación de 17.\n\nAnillo de comandar elementales de agua. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de agua. Además, puedes permanecer de pie sobre superficies líquidas y andar por ellas como si fueran terreno firme. También puedes hablar y entender acuano.\n\nSi ayudas a matar a un elemental de agua mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Puedes respirar bajo el agua y obtienes una velocidad nadando igual a tu velocidad caminando. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: crear o destruir agua (1 carga), controlar agua (3 cargas), muro de hielo (3 cargas) o tormenta de hielo (2 cargas).\n\nAnillo de comandar elementales de aire. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de aire. Además, cuando caigas, descenderás 18 m por asalto y no sufrirás daño por la caída. También puedes hablar y entender aurano.\n\nSi ayudas a matar a un elemental de aire mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Tienes resistencia al daño de relámpago. • Tienes una velocidad volando igual a tu velocidad caminando y puedes levitar. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: muro de viento (1 carga), ráfaga de viento (2 cargas) o relámpago en cadena (3 cargas).\n\nAnillo de comandar elementales de fuego. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de fuego. Además, tienes resistencia al daño de fuego. También puedes hablar y entender ígneo.\n\nSi ayudas a matar a un elemental de fuego mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Eres inmune al daño de fuego. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: bola de fuego (2 cargas), manos ardientes (1 carga) o muro de fuego (3 cargas).\n\nAnillo de comandar elementales de tierra. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de tierra. Además, puedes moverte por terreno difícil compuesto de escombros, rocas o tierra como si fuera terreno normal. También puedes hablar y entender terrano.\n\nSi ayudas a matar a un elemental de tierra mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Tienes resistencia al daño de ácido. • Puedes moverte a través de tierra sólida o roca como si estas superficies fueran terreno difícil. Si acabas tu turno en ellas, irás a parar al espacio sin ocupar más cercano en el que estuviste por última vez. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: moldear la piedra (2 cargas), muro de piedra (3 cargas) o piel pétrea (3 cargas).\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_78cacd5c998f65d7$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:f3814673135c5a3a0681325d';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:f42e832b6b2895b035bada95' and md5(to_jsonb(t)::text)='6dc93fe3080995947607c7306445fd54')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:f42e832b6b2895b035bada95';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_b3e6b109a5d3d596$"Objeto · Precio base · Peso\nAceite (frasco) · 1 pp · 1 lb\n\nAceite. El aceite suele venir en frascos de arcilla con capacidad para 0,5 l. Como acción, puedes esparcir el aceite de este frasco sobre una criatura que esté a 1,5 m o menos de ti o lanzarlo hasta a 6 m, lo que hará que el frasco se rompa con el impacto. En ambos casos, haz un ataque a distancia contra la criatura o el objeto y trata el aceite como un arma improvisada: si tienes éxito, el objetivo quedará cubierto de aceite. Si el objetivo sufre daño de fuego antes de que el aceite se seque (lo que ocurre tras 1 minuto), recibirá 5 de daño de fuego adicional debido al aceite ardiendo. También puedes derramar un frasco de aceite por el suelo, que cubrirá una zona de 1,5 m de lado, siempre y cuando la superficie esté nivelada. Si se prende, el aceite arderá durante 2 asaltos y causará 5 de daño de fuego a cualquier criatura que entre en la zona o acabe su turno en ella. Una criatura solo puede sufrir este daño una vez por turno.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_b3e6b109a5d3d596$::jsonb,true),'{features}',$text_e92c7a74615a59ed$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Aceite. El aceite suele venir en frascos de arcilla con capacidad para 0,5 l. Como acción, puedes esparcir el aceite de este frasco sobre una criatura que esté a 1,5 m o menos de ti o lanzarlo hasta a 6 m, lo que hará que el frasco se rompa con el impacto. En ambos casos, haz un ataque a distancia contra la criatura o el objeto y trata el aceite como un arma improvisada: si tienes éxito, el objetivo quedará cubierto de aceite. Si el objetivo sufre daño de fuego antes de que el aceite se seque (lo que ocurre tras 1 minuto), recibirá 5 de daño de fuego adicional debido al aceite ardiendo. También puedes derramar un frasco de aceite por el suelo, que cubrirá una zona de 1,5 m de lado, siempre y cuando la superficie esté nivelada. Si se prende, el aceite arderá durante 2 asaltos y causará 5 de daño de fuego a cualquier criatura que entre en la zona o acabe su turno en ella. Una criatura solo puede sufrir este daño una vez por turno.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_e92c7a74615a59ed$::jsonb,true),'{rules,definition,description}',$text_203958f9770774af$[{"id":"official-table","rows":[["Aceite (frasco)","1 pp","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Aceite. El aceite suele venir en frascos de arcilla con capacidad para 0,5 l. Como acción, puedes esparcir el aceite de este frasco sobre una criatura que esté a 1,5 m o menos de ti o lanzarlo hasta a 6 m, lo que hará que el frasco se rompa con el impacto. En ambos casos, haz un ataque a distancia contra la criatura o el objeto y trata el aceite como un arma improvisada: si tienes éxito, el objetivo quedará cubierto de aceite. Si el objetivo sufre daño de fuego antes de que el aceite se seque (lo que ocurre tras 1 minuto), recibirá 5 de daño de fuego adicional debido al aceite ardiendo. También puedes derramar un frasco de aceite por el suelo, que cubrirá una zona de 1,5 m de lado, siempre y cuando la superficie esté nivelada. Si se prende, el aceite arderá durante 2 asaltos y causará 5 de daño de fuego a cualquier criatura que entre en la zona o acabe su turno en ella. Una criatura solo puede sufrir este daño una vez por turno.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_203958f9770774af$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:f42e832b6b2895b035bada95';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:f49a0cb0ee5dc6d777c153e6' and md5(to_jsonb(t)::text)='154f16bade6868fece783e9be2c8315e')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:f49a0cb0ee5dc6d777c153e6';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_c69fa0a6289d9a0c$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tendrás una velocidad nadando de 12 m mientras lleves puesto este anillo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_c69fa0a6289d9a0c$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:f49a0cb0ee5dc6d777c153e6';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:f556e8c6ca30b75eb5527eed' and md5(to_jsonb(t)::text)='9d770ef38052e288ea78011f1c3155b4')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:f556e8c6ca30b75eb5527eed';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_5814ac690fd19565$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Las piedras Ioun se llaman así por Ioun, un dios del conocimiento y la profecía adorado en algunos mundos. Existen muchos tipos de piedras Ioun, cada uno de ellos con una combinación distinta de forma y color.\n\nCuando utilices una acción para lanzar una de estas piedras al aire, la piedra girará alrededor de tu cabeza a una distancia de 1d3 × 30 cm y te otorgará un beneficio. A partir de entonces, otra criatura deberá utilizar una acción para agarrar o atrapar la piedra y separarla de ti, ya sea superando una tirada de ataque contra una CA de 24 o una prueba de Destreza (Acrobacias) con CD 24. Puedes utilizar una acción para tomar y guardar la piedra, lo que pone fin a su efecto.\n\nUna piedra tiene una CA de 24, 10 puntos de golpe y resistencia a todo el daño. Se considera un objeto vestido mientras gira alrededor de tu cabeza.\n\nAbsorción mayor (legendaria). Mientras este elipsoide jaspeado en tonos lilas y verdes gire alrededor de tu cabeza, podrás usar tu reacción para cancelar un conjuro de nivel 8 o inferior lanzado por una criatura que puedas ver y que solo te haga objetivo a ti.\n\nEn cuanto la piedra haya cancelado 50 niveles de conjuros, se volverá gris porque su magia se habrá agotado. Si eres el objetivo de un conjuro cuyo nivel sea superior a la cantidad de niveles de conjuro que le queden a la piedra, no podrá cancelarlo.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_5814ac690fd19565$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:f556e8c6ca30b75eb5527eed';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:f59d76529bbbad4366ef31ef' and md5(to_jsonb(t)::text)='8a15040ce75a5291ef61a5c382355729')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:f59d76529bbbad4366ef31ef';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_ac2241f28b1fb2ca$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta gema contiene vestigios de energía elemental. Cuando uses una acción para romperla, invocarás a un elemental como si hubieras lanzado conjurar elemental y la magia de la gema se perderá. El tipo de gema determina el elemental invocado por el conjuro.\n\nEsmeralda · Elemental de agua\nZafiro azul · Elemental de aire\nCorindón rojo · Elemental de fuego\nDiamante amarillo · Elemental de tierra\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_ac2241f28b1fb2ca$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:f59d76529bbbad4366ef31ef';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:f6074a2c384a012868bc89f1' and md5(to_jsonb(t)::text)='96088fa89234a1075c8513f94c44dc36')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:f6074a2c384a012868bc89f1';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_78f99b668bd01213$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras arda incienso en este recipiente, podrás utilizar una acción para pronunciar su palabra de activación e invocar un elemental de aire, como si hubieras lanzado conjurar elemental. El incensario no puede volver a emplearse de esta manera hasta el siguiente amanecer.\n\nEste recipiente de 15 cm de ancho y 30 cm de alto se parece a un cáliz con una tapa decorativa y pesa 0,5 kg.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_78f99b668bd01213$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:f6074a2c384a012868bc89f1';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:f6aefab76047c5788d5cb069' and md5(to_jsonb(t)::text)='c52981a2eccb81c569eed0b30fc3b09b')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:f6aefab76047c5788d5cb069';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_821a5098f9124bf9$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta arma mágica tiene 3 cargas. Mientras la empuñes, podrás usar una acción y gastar 1 carga para desatar una ola de terror. Todas las criaturas de tu elección situadas en un radio de 9 m respecto a ti deberán superar una tirada de salvación de Sabiduría con CD 15 o quedarán asustadas de ti durante 1 minuto. Una criatura asustada de esta manera deberá dedicar sus turnos a tratar de alejarse de ti todo lo que pueda y no podrá acercarse voluntariamente a ningún espacio que se encuentre a 9 m o menos de ti. Tampoco podrá llevar a cabo reacciones. Tan solo podrá realizar la acción de correr o intentar escapar de un efecto que le impida moverse. Si no tiene adónde ir, la criatura podrá usar la acción de esquivar. Al final de cada uno de sus turnos, la criatura podrá repetir la tirada de salvación y, si tiene éxito, se librará del efecto.\n\nLa maza recupera 1d3 cargas empleadas cada día, al amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_821a5098f9124bf9$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:f6aefab76047c5788d5cb069';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:f6f7ba7d85aced20808b7e36' and md5(to_jsonb(t)::text)='984213d991cd95c5847e5bcf65a03b25')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:f6f7ba7d85aced20808b7e36';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_b28931322dcf9526$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este pequeño paquete contiene 1d6 + 4 pizcas de polvo. Puedes utilizar una acción para echar una pizca sobre el agua. El polvo convertirá un cubo de agua de 4,5 m de lado en una bolita del tamaño de una canica, que quedará flotando o en reposo cerca de donde se esparció el polvo. El peso de la bolita es insignificante.\n\nCualquier criatura puede utilizar una acción para golpear la bolita contra una superficie dura, lo que hará añicos la bolita y liberará el agua que absorbió el polvo. Hacer esto acaba con la magia de la bolita.\n\nUn elemental compuesto principalmente por agua y que se exponga a una pizca del polvo deberá realizar una tirada de salvación de Constitución con CD 13; sufrirá 10d6 de daño necrótico si la falla o la mitad del daño si la supera.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_b28931322dcf9526$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:f6f7ba7d85aced20808b7e36';

update public.campaigns set state_revision=state_revision+1,state_updated_at=statement_timestamp(),updated_at=statement_timestamp() where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd';end $text$;select 17 as batch,52 as rows,(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')as revision;commit;